  1163	/**
  1164	 * @brief 更新航向（0–360，正北 0，顺时针）与当前速度。
  1165	 */
  1166	void vmap_view_set_heading(vmap_view_t * view, float heading_deg, float speed_kph)
  1167	{
  1168	    double d = (double)heading_deg;
  1169	    int32_t target;
  1170	    int32_t delta;
  1171	
  1172	    if (!view || !view->heading_up || !view->canvas) {
  1173	        return;
  1174	    }
  1175	    if (!(d >= 0.0) || !(d < 360.0)) {
  1176	        return;                 /* NaN / 越界：宁可不转 */
  1177	    }
  1178	
  1179	    if (!view->heading_valid) {
  1180	        /* 首个航向无条件接受：否则停车时箭头指上、地图还是正北。 */
  1181	        view->heading_deg = d;
  1182	        view->heading_valid = true;
  1183	    } else if (speed_kph >= VMAP_ROT_MIN_KPH) {
  1184	        double diff = d - view->heading_deg;
  1185	
  1186	        /* 圆周低通：先把差值折到 -180..180，避免 359°→1° 绕一整圈。 */
  1187	        while (diff > 180.0) {
  1188	            diff -= 360.0;
  1189	        }
  1190	        while (diff < -180.0) {
  1191	            diff += 360.0;
  1192	        }
  1193	        view->heading_deg += diff * (double)VMAP_ROT_SMOOTH;
  1194	        while (view->heading_deg >= 360.0) {
  1195	            view->heading_deg -= 360.0;
  1196	        }
  1197	        while (view->heading_deg < 0.0) {
  1198	            view->heading_deg += 360.0;
  1199	        }
  1200	    } else {
  1201	        return;                 /* 低速：course 是噪声，保持上次朝向 */
  1202	    }
  1203	
  1204	    /* 航向朝上 ⇒ 地图转 -heading（顺时针为正）。 */
  1205	    target = ((int32_t)lround(-view->heading_deg * 10.0) % 3600 + 3600) % 3600;
  1206	    delta = ((target - view->rot10 + 3600 + 1800) % 3600) - 1800;
  1207	    if (abs((int)delta) < VMAP_ROT_STEP_10) {
  1208	        return;
  1209	    }
