  1211	    /*
  1212	     * 重烘限频：每烘一次 ~138 ms（288×264，0.55 Mpx/s）。1° 步进时若不限频，
  1213	     * 3.6°/s 的弯道会有 3~4 次/秒（≈50% UI）。1200 ms ⇒ 最多 0.83 次/秒 —— 转弯时
  1214	     * 地图比真实航向慢半拍，单步会放大到 ~2°（用户 2026-10-28 接受"旋转慢一些"）。
  1215	     */
  1216	    if (view->last_bake_ms != 0u
  1217	        && lv_tick_elaps(view->last_bake_ms) < VMAP_ROT_BAKE_MIN_MS) {
  1218	        return;                 /* rot10 不动：角度继续累计，下次一次转到位 */
  1219	    }
  1220	    view->last_bake_ms = lv_tick_get();
  1221	
  1222	    view->rot10 = target;
  1223	
  1224	    /* 角度变了 ⇒ R 的整幅内容作废，交给 vmap_rot_track 重烘（见它的条件）。 */
  1225	    …1751 tokens truncated…像素写入
  2449	     * 与 `label_pan_canvas_bounds()` 的标签收集都会把它们裁掉，却仍然要付要素
  2450	     * 遍历（道路层还要按 class 扫 14 遍）和首帧的闪存读。
  2451	     * 代价还落在节拍上：泵每 20 ms 只画 2 张，且从 (tx_max,ty_max) 开始扫，
  2452	     * 多出来的一圈排在**可见区域之前**。实测几何（240x216 视口、margin 128、
  2453	     * scale 1.69）是 16~20 张里只有 4~6 张与画布相交。
  2454	     */
  2455	    tile_range(view->pump_cx, view->pump_cy, view->w, view->h, view->scale, 0,
  2456	        &view->pump_tx_min, &view->pump_ty_min,
  2457	        &view->pump_tx_max, &view->pump_ty_max);
  2458	    view->pump_tx = view->pump_tx_max;
  2459	    view->pump_ty = view->pump_ty_max;
  2460	
  2461	    if (scrolled) {
  2462	        syslog(LOG_INFO,
  2463	            "[map] rebase scroll=%d,%d dirty=%u labels=%d z=%d",
  2464	            (int)sx, (int)sy, (unsigned)view->pump_dirty_n,
  2465	            (int)view->label_col.retained_count, view->zoom);
  2466	    }
  2467	    VMAP_PERF_T1(begin);
