  2470	static bool render_next_tile(vmap_view_t * view)
  2471	{
  2472	    const int32_t tile_size = 256;
  2473	    const double scale = view->scale;
  2474	    vmap_canvas_t canvas;
  2475	    vmap_tile_t tile;
  2476	    float base_x;
  2477	    float base_y;
  2478	    int32_t tx;
  2479	    int32_t ty;
  2480	    int32_t ix1;
  2481	    int32_t iy1;
  2482	    int32_t ix2;
  2483	    int32_t iy2;
  2484	
  2485	    if (view->pump_need_region) {
  2486	        VMAP_PERF_T0();
  2487	        view->pump_need_region = 0;
  2488	        if (view->cache) {
  2489	            myvendor_watchdog_ui_beat();
  2490	            myvendor_watchdog_busy_pump();
  2491	            vmap_tile_cache_ensure_region(view->cache,
  2492	                view->render_lon, view->render_lat);
  2493	            myvendor_watchdog_ui_beat();
  2494	        }
  2495	        VMAP_PERF_T1(warm);
  2496	        return true;
  2497	    }
  2498	
  2499	    while (view->pump_tx >= view->pump_tx_min) {
  2500	        tx = view->pump_tx;
  2501	        ty = view->pump_ty;
  2502	
  2503	        if (!pump_tile_dirty(view, tx, ty)) {
  2504	            VMAP_PERF_T0();
  2505	            if (view->font
  2506	                && vmap_tile_cache_cached(view->cache, view->zoom, (int)tx, (int)ty)
  2507	                && vmap_tile_cache_get(view->cache, view->zoom, (int)tx, (int)ty,
  2508	                    &tile)) {
  2509	                base_x = (float)((tx * tile_size - view->pump_cx) * scale
  2510	                    + view->w / 2.0);
  2511	                base_y = (float)((ty * tile_size - view->pump_cy) * scale
  2512	                    + view->h / 2.0);
  2513	                vmap_label_collector_add_tile(&view->label_col, &tile,
  2514	                    base_x, base_y, (float)scale);
  2515	            }
  2516	            VMAP_PERF_T1(meta);
  2517	            if (!pump_advance(view)) {
  2518	                return false;
  2519	            }
  2520	            continue;
  2521	        }
  2522	
  2523	        if (!vmap_tile_cache_cached(view->cache, view->zoom, (int)tx, (int)ty)) {
  2524	            bool warmed;
  2525	
  2526	            VMAP_PERF_T0();
  2527	            warmed = vmap_tile_cache_warm(view->cache, view->zoom,
  2528	                    (int)tx, (int)ty);
  2529	            VMAP_PERF_T1(warm);
  2530	            if (!warmed) {
  2531	                /* 邻格 heap 暂时放不下：跳过，继续画已在 PSRAM 的瓦片。 */
  2532	                if (!pump_advance(view)) {
  2533	                    return false;
  2534	                }
  2535	                continue;
  2536	            }
  2537	            VMAP_PERF_N(n_warms);
  2538	            return true;
  2539	        }
  2540	
  2541	        view_canvas(view, &canvas, true);
  2542	        base_x = (float)((tx * tile_size - view->pump_cx) * scale
  2543	            + view->w / 2.0);
  2544	        base_y = (float)((ty * tile_size - view->pump_cy) * scale
  2545	            + view->h / 2.0);
  2546	
  2547	        if (vmap_tile_cache_get(view->cache, view->zoom, (int)tx, (int)ty,
  2548	                &tile)) {
  2549	            uint32_t st = 0u;
  2550	            uint32_t by = 0u;
  2551	
  2552	            VMAP_PERF_T0();
  2553	            vmap_render_stat_reset();
  2554	            vmap_render_draw_tile(&canvas, &tile, base_x, base_y, (float)scale,
  2555	                view->scratch, VMAP_SCRATCH_CAP);
  2556	            VMAP_PERF_T1(tile);
  2557	            VMAP_PERF_N(n_tiles);
  2558	            vmap_render_stat_get(&st, &by);
  2559	            s_pf_stores += st;
  2560	            s_pf_bytes += by;
  2561	            if (view->font) {
  2562	                vmap_label_collector_add_tile(&view->label_col, &tile,
  2563	                    base_x, base_y, (float)scale);
  2564	            }
  2565	
  2566	            ix1 = (int32_t)floor((double)base_x);
  2567	            iy1 = (int32_t)floor((double)base_y);
  2568	            ix2 = (int32_t)ceil((double)base_x + 256.0 * scale);
  2569	            iy2 = (int32_t)ceil((double)base_y + 256.0 * scale);
  2570	            if (view->pump_dirty_n == 0) {
  2571	                vmap_view_invalidate_canvas_area(view, ix1, iy1, ix2, iy2);
  2572	            } else {
  2573	                uint8_t di;
  2574	
  2575	                for (di = 0; di < view->pump_dirty_n; di++) {
  2576	                    int32_t vx1 = ix1 > view->pump_dirty_x1[di]
  2577	                        ? ix1 : view->pump_dirty_x1[di];
  2578	                    int32_t vy1 = iy1 > view->pump_dirty_y1[di]
  2579	                        ? iy1 : view->pump_dirty_y1[di];
  2580	                    int32_t vx2 = ix2 < (view->pump_dirty_x2[di] - 1)
  2581	                        ? ix2 : (view->pump_dirty_x2[di] - 1);
  2582	                    int32_t vy2 = iy2 < (view->pump_dirty_y2[di] - 1)
  2583	                        ? iy2 : (view->pump_dirty_y2[di] - 1);
  2584	
  2585	                    if (vx1 <= vx2 && vy1 <= vy2) {
  2586	                        vmap_view_invalidate_canvas_area(view, vx1, vy1, vx2, vy2);
  2587	                    }
  2588	                }
  2589	            }
  2590	        }
  2591	
  2592	        if (!pump_advance(view)) {
  2593	            return false;
  2594	        }
  2595	        return true;
  2596	    }
  2597	
  2598	    return false;
  2599	}
