  2601	/*
  2602	 * Canvas stack, bottom → top:
  2603	 *   map tiles (already in buffer) → nav → labels → REC line → REC numbers.
  2604	 * clip_dirty: follow-rebase only restamps the new edge, so interior ink is not
  2605	 * redrawn fat. Labels use the same dirty rects.
  2606	 */
  2607	static void stamp_overlays(vmap_view_t * view, bool labels)
  2608	{
  2609	    vmap_canvas_t canvas;
  2610	    lv_area_t label_drawn;
  2611	    bool labels_drawn = false;
  2612	
  2613	    if (!view || !view->canvas || !view->cbuf) {
  2614	        return;
  2615	    }
  2616	
  2617	    view_canvas(view, &canvas, true);
  2618	
  2619	#if VMAP_ROUTE_ENABLE
  2620	    if (view->route) {
  2621	        VMAP_PERF_T0();
  2622	        vmap_route_paint_to_canvas(view->route, &canvas, view);
  2623	        VMAP_PERF_T1P(VMAP_PERF_NAV_SLOT());
  2624	    }
  2625	#endif
  2626	
  2627	    /* 航向朝上时路名会随画布转成斜字：该模式不烘焙标签（第一版取舍，见
  2628	     * vmap_config.h 的说明）。 */
  2629	    if (labels && view->font && !view->heading_up
  2630	        && view->label_col.count > 0) {
  2631	        VMAP_PERF_T0();
  2632	        labels_drawn = vmap_label_paint_to_canvas(
  2633	            view->canvas, &view->label_col, view->font,
  2634	            view->scale, view->pump_dirty_n,
  2635	            view->pump_dirty_x1, view->pump_dirty_y1,
  2636	            view->pump_dirty_x2, view->pump_dirty_y2, &label_drawn);
  2637	        VMAP_PERF_T1(label);
  2638	        VMAP_PERF_NB(n_labels, view->label_col.count);
  2639	    }
  2640	
  2641	#if VMAP_TRACK_ENABLE
  2642	    if (view->track) {
  2643	        if (labels_drawn && canvas.clip_n > 0u) {
  2644	            int32_t x1 = label_drawn.x1;
  2645	            int32_t y1 = label_drawn.y1;
  2646	            int32_t x2 = label_drawn.x2 + 1;
  2647	            int32_t y2 = label_drawn.y2 + 1;
  2648	            uint8_t i;
  2649	
  2650	            /*
  2651	             * New labels may be outside the tile dirty edge. Expand the REC
  2652	             * clip to their union so track ink is restored above those words.
  2653	             */
  2654	            for (i = 0; i < canvas.clip_n; i++) {
  2655	                if (canvas.clip_x1[i] < x1) {
  2656	                    x1 = canvas.clip_x1[i];
  2657	                }
  2658	                if (canvas.clip_y1[i] < y1) {
  2659	                    y1 = canvas.clip_y1[i];
  2660	                }
  2661	                if (canvas.clip_x2[i] > x2) {
  2662	                    x2 = canvas.clip_x2[i];
  2663	                }
  2664	                if (canvas.clip_y2[i] > y2) {
  2665	                    y2 = canvas.clip_y2[i];
  2666	                }
  2667	            }
  2668	            vmap_render_clip_reset(&canvas);
  2669	            vmap_render_clip_add(&canvas, x1, y1, x2, y2);
  2670	        }
  2671	        VMAP_PERF_T0();
  2672	        vmap_track_paint_to_canvas(view->track, &canvas);
  2673	        VMAP_PERF_T1P(VMAP_PERF_TRACK_SLOT());
  2674	    }
  2675	#endif
  2676	}
  2677	
  2678	void vmap_view_stamp_nav_then_track(vmap_view_t * view)
  2679	{
  2680	    stamp_overlays(view, false);
  2681	    if (view && view->canvas) {
  2682	        lv_obj_invalidate(view->canvas);
  2683	    }
  2684	    vmap_perf_stamp_end((uint32_t)(view ? view->zoom : 0));
  2685	}
