  2687	static void render_finish(vmap_view_t * view)
  2688	{
  2689	    stamp_overlays(view, true);
  2690	    /* 必须在 dvfs_map_busy(false) 之前：MAP hold 期间 HCLK 才是被钉住的那档。
  2691	     * 也要在 pump_dirty_n 被清零之前取，脏区条数是判"全量重画 / scroll 补边"的依据。 */
  2692	    vmap_perf_frame_end((uint32_t)view->zoom, (uint32_t)view->pump_dirty_n);
  2693	
  2694	#if defined(CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE) && CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE
  2695	    bicycle_inval_probe_tag("vmap_render");
  2696	#endif
  2697	    view->render_rev++;
  2698	    view->paint_zoom = view->zoom;
  2699	    view->paint_scale = view->scale;
  2700	    view->pump_phase = 0;
  2701	    view->pump_need_region = 0;
  2702	    view->pump_dirty_n = 0;
